// Port of process_time_off() from the LangGraph notebook.
const userId = String(query.user_id ?? '1');
const BALANCES = { '1': 10 };
const balance = BALANCES[userId] ?? 10;

const start = new Date(String(query.start_date) + 'T00:00:00Z');
const end = new Date(String(query.end_date) + 'T00:00:00Z');

if (isNaN(start.getTime()) || isNaN(end.getTime())) {
  return JSON.stringify({
    status: 'error',
    message: 'start_date and end_date must both be valid dates in YYYY-MM-DD format.',
  });
}

const MS_PER_DAY = 24 * 60 * 60 * 1000;
// Inclusive of both the start and the end day, same as the notebook (+ 1).
const daysRequested = Math.round((end.getTime() - start.getTime()) / MS_PER_DAY) + 1;

if (daysRequested <= 0) {
  return JSON.stringify({
    status: 'error',
    message: 'end_date must be on or after start_date.',
  });
}

if (daysRequested > balance) {
  return JSON.stringify({
    status: 'error',
    message: 'Time off request failed. You only have ' + balance +
      ' days of remaining leave but requested ' + daysRequested + ' days.',
  });
}

const remaining = balance - daysRequested;

return JSON.stringify({
  status: 'success',
  message: 'Time off request processed successfully for ' + daysRequested +
    ' day(s). Your remaining time off balance is ' + remaining + '.',
});

