// Port of submit_expense() from the LangGraph notebook.
const AUTO_APPROVE_LIMITS = { meals: 150, travel: 500, equipment: 200 };

const userId = String(query.user_id ?? '1');
const amount = Number(query.amount);
const category = String(query.category ?? '').toLowerCase().trim();
const description = String(query.description ?? '');

if (!isFinite(amount) || amount <= 0) {
  return JSON.stringify({ status: 'error', message: 'amount must be a positive number.' });
}

const limit = AUTO_APPROVE_LIMITS[category] !== undefined ? AUTO_APPROVE_LIMITS[category] : 100;

// Deterministic stand-in for Python's hash() so the same claim gets the same id.
const seed = userId + '|' + amount + '|' + description;
let h = 0;
for (let i = 0; i < seed.length; i++) {
  h = (h * 31 + seed.charCodeAt(i)) % 1000000007;
}
const claimId = 'EXP-' + String(h % 10000).padStart(4, '0');

if (amount <= limit) {
  return JSON.stringify({
    status: 'approved',
    claim_id: claimId,
    message: 'Expense of $' + amount.toFixed(2) + ' (' + category +
      ') auto-approved. Reimbursement will be included in the next payroll cycle.',
  });
}

return JSON.stringify({
  status: 'pending_review',
  claim_id: claimId,
  message: 'Expense of $' + amount.toFixed(2) + ' (' + category + ') exceeds the $' + limit +
    ' auto-approval limit and has been routed to your manager for review.',
});

