// One output item per uploaded file, tagged with a category derived from the
// file name. Replaces the hard-coded POLICIES dict from the notebook.
//
//   meals.md              -> category "meals"
//   Travel_Policy_v3.pdf  -> category "travel"
//   parking.docx          -> category "parking"   (no keyword match -> slug of the name)

const KNOWN_CATEGORIES = ['meals', 'travel', 'equipment'];

// Extensions the Default Data Loader reads as plain text. Browsers often send
// .md as application/octet-stream, which the "auto" loader cannot dispatch, so
// we normalise the mime type here.
const TEXT_EXTENSIONS = ['md', 'markdown', 'txt', 'text', 'rst'];

const out = [];

for (const item of $input.all()) {
  const binary = item.binary ?? {};

  for (const key of Object.keys(binary)) {
    const bin = binary[key];
    const fileName = bin.fileName ?? key;

    const stem = fileName.replace(/\.[^.]+$/, '');
    const ext = (fileName.split('.').pop() ?? '').toLowerCase();
    const slug = stem
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '_')
      .replace(/^_+|_+$/g, '');

    const matched = KNOWN_CATEGORIES.find((c) => slug.includes(c));

    const normalised =
      TEXT_EXTENSIONS.includes(ext) && !String(bin.mimeType ?? '').startsWith('text/')
        ? { ...bin, mimeType: 'text/plain' }
        : bin;

    out.push({
      json: {
        file_name: fileName,
        category: matched ?? (slug || 'other'),
        matched_known_category: Boolean(matched),
        form_field: key,
        submitted_at: item.json.submittedAt ?? null,
      },
      binary: { data: normalised },
    });
  }
}

if (out.length === 0) {
  throw new Error(
    'No file found on the form submission. Attach at least one document and submit again.'
  );
}

return out;
